import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { INTERVALS, MAX_BOX, MIN_BOX, type LanguageCode } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { Burst } from '@/components/ui/Burst.js';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { platform } from '@/lib/platform/index.js';
import { noteFirstWin } from './state.js';
import styles from './FirstWin.module.css';

/**
 * "Your first word is saved." (onboarding v2 spec §4.10): the five boxes
 * with the word dropped into the one its first answer put it in, the
 * honest line about when it comes back, the streak's first day and one
 * button. It is today's big moment, said once.
 *
 * Box 2 when the flashcard was answered right (back tomorrow, then
 * `INTERVALS[2]` days); box 1 otherwise, including closing before answering
 * (back later today). Every number comes from the engine's INTERVALS.
 */
export function FirstWin({
  headword,
  lang,
  box,
  streak,
  onContinue,
}: {
  headword: string;
  lang: LanguageCode;
  /** The box the graded answer left the word in (1 when there was none). */
  box: number;
  /** The streak after the graded answer (0 when there was none). */
  streak: number;
  onContinue: () => void;
}): React.JSX.Element {
  const target = Math.min(MAX_BOX, Math.max(MIN_BOX, box)) - 1;
  const missed = target === 0;
  const heading = useRef<HTMLHeadingElement>(null);
  const boxes = useRef<HTMLDivElement>(null);
  const chip = useRef<HTMLSpanElement>(null);
  const when = useRef<HTMLSpanElement>(null);
  const [place, setPlace] = useState<{ chip: number; when: number } | undefined>(undefined);

  useEffect(() => {
    heading.current?.focus({ preventScroll: true });
    platform.haptics.success();
    void noteFirstWin().catch(() => undefined);
  }, []);

  // The chip and its label sit over the target box, kept inside the row so
  // a long word at box 1 or box 5 is never cut off at the screen's edge.
  useLayoutEffect(() => {
    const measure = (): void => {
      const row = boxes.current;
      const cell = row?.children[target];
      if (row === null || !(cell instanceof HTMLElement)) return;
      const rowBox = row.getBoundingClientRect();
      const cellBox = cell.getBoundingClientRect();
      const centre = cellBox.left - rowBox.left + cellBox.width / 2;
      const clamp = (half: number): number => Math.max(half, Math.min(rowBox.width - half, centre));
      setPlace({
        chip: clamp((chip.current?.offsetWidth ?? 0) / 2),
        when: clamp((when.current?.offsetWidth ?? 0) / 2),
      });
    };
    measure();
    window.addEventListener('resize', measure);
    return () => {
      window.removeEventListener('resize', measure);
    };
  }, [target]);

  const sub = t(missed ? 'onb.done.subMissed' : 'onb.done.sub', {
    next: t('onboarding.intervalDays', { n: INTERVALS[2] }),
  }).split('{word}');

  return (
    <main className={styles.screen}>
      <span className={styles.burst} aria-hidden="true">
        <Burst size="takeover" origin="center" />
      </span>
      <div className={styles.scroll}>
        <div className={styles.col}>
          <div className={styles.stage} aria-hidden="true">
            <div ref={boxes} className={styles.boxes}>
              {INTERVALS.map((_, index) => (
                <div key={index} className={cx(styles.box, index === target && styles.lit)}>
                  {index + 1}
                </div>
              ))}
            </div>
            <span
              className={styles.chipPlace}
              style={place === undefined ? { visibility: 'hidden' } : { left: `${String(place.chip)}px` }}
            >
              <span ref={chip} className={styles.chip}>
                <Bilingual lang={lang}>{headword}</Bilingual>
              </span>
            </span>
            <span
              ref={when}
              className={styles.when}
              style={place === undefined ? { visibility: 'hidden' } : { left: `${String(place.when)}px` }}
            >
              {t(missed ? 'onb.done.whenToday' : 'onb.done.when')}
            </span>
          </div>
          <p className="sr-only">{t('onb.done.boxes', { word: headword, n: target + 1 })}</p>
          <h1 ref={heading} className={styles.title} tabIndex={-1}>
            {t('onb.done.title')}
          </h1>
          <p className={styles.sub}>
            {sub[0]}
            <b>
              <Bilingual lang={lang}>{headword}</Bilingual>
            </b>
            {sub.slice(1).join('')}
          </p>
          {streak === 1 && (
            <span className={styles.streak}>
              <Icon name="flameLine" size={16} weight={2} />
              {t('onb.done.streak')}
            </span>
          )}
        </div>
      </div>
      <div className={styles.foot}>
        <button type="button" className={cx(styles.primary, 'press')} onClick={onContinue}>
          {t('onb.continue')}
        </button>
      </div>
    </main>
  );
}
