/** The celebration sheet, its own chunk: loaded only when a takeover fires. */
const Takeover = lazy(() => import('@/features/celebrate/Takeover.js'));

/**
 * Accuracy at or above which the tile wears the app's colour. Below it the
 * number is plain: a celebratory green on 20% read as praise for a bad day,
 * and most cards are self-graded, so the app never cheers a score anyway.
 */
export const ACCURACY_ACCENT_MIN = 50;

/**
 * What the session that just ended was, in the words the screen that opened
 * it used. It said "Daily practice" after every session until 2026-09-30,
 * including a starred run or an audio one.
 */
function deckTitle(deck: Deck, params: URLSearchParams): string {
  switch (deck) {
    case 'audio':
      return t('today.audioTitle');
    case 'starred':
      return t('today.starredTitle');
    case 'struggling':
      return t('today.strugglingTitle');
    case 'confusables':
      return t('today.confusablesTitle');
    case 'tricky':
      return t('today.trickyTitle');
    case 'notebook':
      return t('summary.deckNotebook');
    case 'group':
      return t('summary.deckGroup');
    case 'mine':
      return t('summary.deckMine');
    case 'level': {
      const level = params.get('level');
      return level === null ? t('summary.deck') : t('summary.deckLevel', { level });
    }
    case 'topic':
      return params.get('topic') ?? t('summary.deck');
    case 'kind': {
      const kind = KINDS.find((one) => one === params.get('kind'));
      return kind === undefined ? t('summary.deck') : t(`kind.${kind satisfies Kind}`);
    }
    case 'daily':
      return t('summary.deck');
  }
}

interface SummaryProps {
  summary: SessionSummary;
  /*
   * The languages, and a lookup per notebook. A session over every notebook
   * ends with a list of missed words from several of them, and each one has
   * to be set in its own language rather than in the active notebook's.
   */
  context: {
    targetLang: LanguageCode;
    meaningLang: LanguageCode;
    byNotebook: Record<string, { targetLang: LanguageCode; meaningLang: LanguageCode }>;
  };
  deck: Deck;
  /** How many cards are still waiting after this session. */
  remaining?: number;
  /** Whether this client shows the SRS v2 screens (the leech prompt among them). */
  srs?: boolean;
  onDone: () => void;
}

/**
 * What the session achieved (app audit 2026-10-22, owner-approved): a head
 * on the onboarding story's ground with the session's celebration, three big
 * numbers (words practised, right, the streak, which counts up when it
 * rose), a line of progress, and when each word comes back, the missed ones
 * first. Done stays at the bottom of the screen however long the list is,
 * with "Add a word you met today" under it.
 */
export function Summary({
  summary,
  context,
  deck,
  remaining = 0,
  srs = false,
  onDone,
}: SummaryProps): React.JSX.Element {
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const masteredNames = summary.mastered.slice(0, 3).map((word) => word.headword);
  // A finished session changes tonight's plan: the streak nudge has nothing
  // left to save. Done here as well as after the sync, which may be hours
  // away on a phone without a connection.
  useEffect(() => {
    void syncReminder().catch(() => undefined);
  }, []);
  const learn = useLearn();
  useCountSummary(learn);
  // The session's celebration, if it was one (features/celebrate): decided
  // before anything is drawn, so a moment never arrives late and pushes the
  // page down. Most sessions are not one, and wait only for local reads.
  const candidate = useTipCandidate(learn, summary, srs);
  const moment = useSummaryMoment(summary, candidate);
  const pick: Pick = moment.pick;
  const langOf = (notebookId: string): LanguageCode => (context.byNotebook[notebookId] ?? context).targetLang;
  const mainCopy = pick.main === undefined ? undefined : momentCopy(pick.main, langOf);
  const extraCopy = pick.extra === undefined ? undefined : momentCopy(pick.extra, langOf);
  const burst = pick.main?.size === 'burst' ? mainCopy : undefined;
  const lineCopy = pick.main?.size === 'line' ? mainCopy : extraCopy;
  const [takeoverOpen, setTakeoverOpen] = useState(true);
  // A celebration line and a tip are never on one screen: on the summary the
  // tip wins (the moment was decided knowing it, and spent the line), and a
  // big moment keeps the tip under it. The first mastered word's takeover
  // says what its tip says, so that tip is put away.
  const absorbsMastered = pick.main?.id === 'firstMastered';
  const tipAllowed = moment.ready && lineCopy === undefined;
  const tip = useHeldTip(
    tipAllowed && !(absorbsMastered && candidate?.id === 'firstMastered') ? candidate?.id : undefined,
    'summary',
  );
  useEffect(() => {
    if (absorbsMastered) void markTipShown('firstMastered');
  }, [absorbsMastered]);
  // One touch, with the moment, on the phone apps.
  const felt = useRef(false);
  useEffect(() => {
    if (!moment.ready || felt.current || pick.main === undefined) return;
    felt.current = true;
    feel(pick.main.size);
    void noteMilestone(pick.main.size, pick.main.id, undefined, pick.main.count).catch(() => undefined);
  }, [moment.ready, pick.main]);
  // Words the leech prompt names are remembered, for "stuck this time" later.
  useEffect(() => {
    if (srs && summary.slipping.length > 0) void noteFlagged(summary.slipping.map((one) => one.word.id));
  }, [srs, summary.slipping]);

  if (!moment.ready) {
    // A few frames at most: the same ground, nothing on it yet.
    return <main className={styles.screen} aria-busy="true" />;
  }

  const accuracyValue = summary.reviewed === 0 ? 0 : (summary.correct / summary.reviewed) * 100;
  // Words, not answers: a missed word asked twice is one word practised.
  const practised = summary.moves.length > 0 ? summary.moves.length : summary.reviewed;
  const movedUp = summary.moves.filter((move) => !move.kept && move.to > move.from).length;
  // The line moment that says the day is done is the same fact as the
  // head's second line, so it is said once, there.
  const lineMoment = pick.main?.size === 'line' ? pick.main : pick.extra;
  const lineIsDone = lineMoment?.id === 'allDone';
  const doneLine =
    remaining > 0
      ? plural(remaining, 'summary.moreWaitingOne', 'summary.moreWaiting', { count: remaining })
      : deck === 'daily' || lineIsDone
        ? t('summary.allDone')
        : undefined;
  const shownLine = lineIsDone ? undefined : lineCopy;

  return (
    <main className={styles.screen}>
      <div className={styles.body}>
        {/* The head: the onboarding story's ground, with the session's
            celebration on it when there is one (app audit 2026-10-22). */}
        <section
          className={cx(styles.head, burst !== undefined && styles.headMoment)}
          aria-labelledby="summary-title"
        >
          {burst !== undefined && mainCopy !== undefined ? (
            <>
              <span className={styles.burst} aria-hidden="true">
                <Burst size="burst" />
              </span>
              <Badge icon={mainCopy.icon} />
              <p className={styles.eyebrow}>{t('summary.title')}</p>
              <h1 id="summary-title" className={styles.title}>
                {mainCopy.title ?? deckTitle(deck, params)}
              </h1>
              <p className={styles.momentText}>{mainCopy.line}</p>
              {doneLine !== undefined && <p className={styles.accent}>{doneLine}</p>}
            </>
          ) : (
            <>
              {/* As the approved mockup has it: what was done is the headline,
                  which deck it was is the line above (app audit 2026-10-22). */}
              <p className={styles.eyebrow}>{t('summary.eyebrowDeck', { deck: deckTitle(deck, params) })}</p>
              <h1 id="summary-title" className={styles.title}>
                {plural(practised, 'summary.headOne', 'summary.head', { count: practised })}
              </h1>
              {doneLine !== undefined && <p className={styles.accent}>{doneLine}</p>}
            </>
          )}
          {shownLine !== undefined && (
            <p className={styles.momentLine} data-moment="">
              <span className={styles.momentMark} aria-hidden="true">
                <Icon name={shownLine.icon === 'boxes' ? 'check' : shownLine.icon} size={15} weight={2.2} />
              </span>
              <span>
                {shownLine.title !== undefined && (
                  <>
                    <strong>{shownLine.title}</strong>{' '}
                  </>
                )}
                {shownLine.line}
              </span>
            </p>
          )}
        </section>
        {mainCopy !== undefined && pick.main?.size !== 'takeover' && (
          <Announce text={spoken(mainCopy, extraCopy)} />
        )}

        <div className={styles.tiles}>
          <div className={styles.tile}>
            <CountUp
              className={styles.tileValue}
              value={practised}
              label={plural(practised, 'summary.wordPractised', 'summary.wordsPractised', {
                count: practised,
              })}
            />
            <span className={styles.tileLabel}>
              {plural(practised, 'summary.wordPractisedLabel', 'summary.wordsPractisedLabel')}
            </span>
          </div>
          <div className={styles.tile}>
            <span
              className={cx(styles.tileValue, accuracyValue >= ACCURACY_ACCENT_MIN && styles.tileAccent)}
              aria-label={`${accuracy(summary.correct, summary.reviewed)} ${t('summary.right')}`}
            >
              {accuracy(summary.correct, summary.reviewed)}
            </span>
            <span className={styles.tileLabel} aria-hidden="true">
              {t('summary.right')}
            </span>
          </div>
          <div className={cx(styles.tile, summary.streak > summary.streakBefore && styles.tileRose)}>
            <CountUp
              className={cx(styles.tileValue, styles.tileGold)}
              value={summary.streak}
              from={Math.min(summary.streakBefore, summary.streak)}
              label={t('summary.streakSpoken', { count: summary.streak })}
            />
            <span className={styles.tileLabel}>{t('summary.streak')}</span>
          </div>
        </div>

        {(movedUp > 0 || summary.mastered.length > 0) && (
          <div className={styles.progress}>
            {movedUp > 0 && (
              <p className={styles.progressLine}>
                <Icon name="chevronUp" size={15} weight={2.2} className={styles.progressIcon} />
                {plural(movedUp, 'summary.movedUpLineOne', 'summary.movedUpLine', { count: movedUp })}
              </p>
            )}
            {summary.mastered.length > 0 && (
              <p className={cx(styles.progressLine, styles.progressMastered)}>
                <Icon name="check" size={15} weight={2.4} className={styles.progressIcon} />
                <span>
                  {t(
                    summary.mastered.length > 3
                      ? 'summary.masteredMore'
                      : summary.mastered.length === 1
                        ? 'summary.masteredOne'
                        : 'summary.masteredLine',
                    { words: masteredNames.join(', ') },
                  )}
                  {/* The first word to reach the last step (the new learner's journey, M9). */}
                  {tip === 'firstMastered' && (
                    <span className={styles.masteredTip}>
                      {t('tip.firstMastered', { days: MASTERED_STEPS[0] })}
                    </span>
                  )}
                </span>
              </p>
            )}
          </div>
        )}

        {tip === 'firstWeekFreeze' && <WeekFreeze />}

        {/* The daily reminder, offered once on the first day's summary (shells only). */}
        {/* Never beside a celebration line either: one line of that kind a screen. */}
        {tip === undefined && shownLine === undefined && <FirstReminder />}
        {/* The same offer in a browser tab (marketer's F3, 2026-10-18): under a
            tip, never hidden by it, and never while a takeover is open. */}
        {!(pick.main?.size === 'takeover' && takeoverOpen) && <SummaryWebReminder />}

        <ComeBack
          moves={summary.moves}
          missed={summary.missed}
          today={summary.today}
          langOf={(word) => langsOf(context, word).targetLang}
        />

        {/* SRS v2: when one of the notebook's own rules decided what an
            answer did, say so and lead to where those rules live. Only then:
            a link under every session would be noise. */}
        {srs && (summary.rules.kept || summary.rules.backTwo) && (
          <p className={styles.rules}>
            <span className={styles.rulesText}>
              {[
                summary.rules.kept ? t('summary.rulesKept') : undefined,
                summary.rules.backTwo ? t('summary.rulesBackTwo') : undefined,
              ]
                .filter((line) => line !== undefined)
                .join(' ')}
            </span>
            <Link to={settingsPath('schedule')} className={styles.rulesLink}>
              {t('schedule.title')}
              <Icon name="chevronRight" size={14} weight={2.2} className={styles.rulesGo} />
            </Link>
          </p>
        )}

        {srs && summary.slipping.length > 0 && (
          <LeechCard words={summary.slipping} firstTime={tip === 'firstLeech'} />
        )}

        {remaining > 0 && (
          <button
            type="button"
            className={styles.secondary}
            onClick={() => {
              // The same session again, with everything that decided what
              // it contained kept: the ids of a group, the level or kind
              // being drilled, whether it runs across notebooks. Naming
              // only the deck would have sent a group session back with no
              // ids, which is a session with nothing in it.
              const again = new URLSearchParams(params);
              again.set('deck', deck);
              again.set('again', String(Date.now()));
              void navigate(`/session?${again.toString()}`, { replace: true });
            }}
          >
            {t('summary.keepGoing', { count: remaining })}
          </button>
        )}
      </div>

      {/* Done is always in reach, however long the list (owner, 2026-10-22). */}
      <div className={styles.actions}>
        <button type="button" className={styles.primary} onClick={onDone}>
          {t('summary.done')}
        </button>
        <button
          type="button"
          className={styles.addWord}
          onClick={() => {
            void navigate('/notebook?add=1', { replace: true });
          }}
        >
          <Icon name="plus" size={16} weight={2.2} />
          {t('summary.addWord')}
        </button>
      </div>
      {pick.main?.size === 'takeover' && mainCopy !== undefined && takeoverOpen && (
        <Suspense fallback={null}>
          <Takeover
            copy={mainCopy}
            action={t('celebrate.lovely')}
            onClose={() => {
              setTakeoverOpen(false);
            }}
          />
        </Suspense>
      )}
    </main>
  );
}

/** What the live region says: the moment's title and its line, then the line under it. */
function spoken(main: MomentCopy, extra: MomentCopy | undefined): string {
  return [main.titleText, main.lineText, extra?.titleText, extra?.lineText]
    .filter((part): part is string => part !== undefined && part !== '')
    .join('. ');
}

/**
 * Counts this summary for the learner's tips (`noteSummary`), once, in an
 * effect, because counting writes. With the feature off nothing is counted.
 */
function useCountSummary(learn: ReturnType<typeof useLearn>): void {
  const settled = learn.on && learn.tips !== null;
  const counted = useRef(false);
  useEffect(() => {
    if (!settled || counted.current) return;
    counted.current = true;
    void noteSummary();
  }, [settled]);
}

/**
 * The one tip a summary may carry (the new learner's journey): the first
 * word that keeps slipping (M10), the first word in box 5 (M9), or the
 * first week in a row while streak freeze is off (M12). Null until what
 * decides it has been read (the tips and the freeze), so the celebration
 * can be decided knowing it; held for this summary once shown.
 */
function useTipCandidate(
  learn: ReturnType<typeof useLearn>,
  summary: SessionSummary,
  srs: boolean,
): { id: TipId | undefined } | null {
  const freeze = useLiveQuery<FreezeView | null>(async () => loadFreeze(summary.today), null, [
    summary.today,
  ]);
  if (!learn.ready || freeze === null) return null;
  const tips = learn.on ? learn.tips : null;
  // With the feature on, wait for this device's tips to be settled.
  if (learn.on && tips === null) return null;
  return {
    id: pickTip(
      'summary',
      {
        today: summary.today,
        wants: {
          firstLeech: srs && summary.slipping.length > 0,
          firstMastered: summary.mastered.length > 0,
          firstWeekFreeze: freeze.offered && summary.streak >= FREEZE_EVERY,
        },
      },
      tips,
    ),
  };
}

/**
 * Seven days in a row, and streak freeze is off (M12): the one moment the
 * offer means something. The same switch as Settings and the streak sheet,
 * waiting the same way for older apps and the network; it reads the flag's
 * copy rather than asking the server again.
 */
function WeekFreeze(): React.JSX.Element | null {
  const { ready, online, saving, older, status, failed, change } = useFreezeSwitch(false);
  const [done, setDone] = useState(false);
  if (done) return null;
  return (
    <div className={styles.freeze}>
      <p className={styles.freezeText}>{t('tip.firstWeekFreeze')}</p>
      {ready && !older && (
        <button
          type="button"
          className={styles.freezeAction}
          disabled={saving || !online}
          onClick={() => {
            void change(true).then((on) => {
              if (on) setDone(true);
            });
          }}
        >
          {t('streakFreeze.turnOn')}
        </button>
      )}
      {ready && older && <p className={styles.freezeNote}>{t('streakFreeze.olderDevices')}</p>}
      {ready && !online && !older && <p className={styles.freezeNote}>{t('streakFreeze.offline')}</p>}
      {status !== undefined && status !== '' && (
        <p className={cx(styles.freezeNote, failed && styles.freezeError)} role="status">
          {status}
        </p>
      )}
    </div>
  );
}

/** A word's own notebook's languages, falling back to the one in view. */
function langsOf(
  context: SummaryProps['context'],
  word: Word,
): { targetLang: LanguageCode; meaningLang: LanguageCode } {
  return context.byNotebook[word.notebookId] ?? context;
}
