import type { LanguageCode, Word } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { Speaker } from './Speaker.js';
import { metaOf } from './meta.js';
import styles from './Card.module.css';

interface AnswerProps {
  word: Word;
  targetLang: LanguageCode;
  meaningLang: LanguageCode;
  /** Opens the note editor, as the prototype's memo block does. */
  onEditMemo?: (() => void) | undefined;
}

/**
 * The back of a card, as the prototype composes it: the headword and its
 * meta over a rule, then every sense with its example, the learner's note,
 * the collocations, and any correction the notebook carried.
 */
export function Answer({ word, targetLang, meaningLang, onEditMemo }: AnswerProps): React.JSX.Element {
  const meanings = word.meanings ?? [];
  const multi = meanings.length > 1;
  const collocations = word.collocations ?? [];
  const memo = word.progress?.memo;

  return (
    <div className={styles.back}>
      <div className={styles.backHead}>
        <div>
          <div className={styles.headword}>
            <Bilingual lang={targetLang}>{word.headword}</Bilingual>
          </div>
          <div className={styles.headMeta}>
            {metaOf(word).map((part) => (
              <span key={part} className={styles.headTag}>
                {part}
              </span>
            ))}
          </div>
        </div>
        <Speaker text={word.headword} lang={targetLang} />
      </div>

      <div className={styles.senses}>
        {meanings.map((sense, index) => {
          const example = sense.examples?.[0];
          return (
            <div key={`${sense.meaning}-${String(index)}`} className={styles.sense}>
              <div className={styles.senseRow}>
                {multi && <span className={styles.senseNumber}>{index + 1}</span>}
                <span className={styles.meaning}>
                  <Bilingual lang={meaningLang}>{sense.meaning}</Bilingual>
                </span>
              </div>
              {example !== undefined && (
                <div className={styles.example}>
                  <div className={styles.exampleText}>
                    <Bilingual lang={targetLang}>{example.sentence}</Bilingual>
                  </div>
                  {example.translation !== undefined && (
                    <div className={styles.exampleTranslation}>
                      <Bilingual lang={meaningLang}>{example.translation}</Bilingual>
                    </div>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {memo !== undefined && memo !== '' && (
        <button
          type="button"
          className={styles.memo}
          onClick={(event) => {
            event.stopPropagation();
            onEditMemo?.();
          }}
        >
          <Icon name="note" size={16} weight={2} className={styles.memoIcon} />
          <span dir="auto">{memo}</span>
        </button>
      )}

      {collocations.length > 0 && (
        <div className={styles.collocations}>
          {collocations.map((phrase) => (
            <span key={phrase} className={styles.collocation}>
              {phrase}
            </span>
          ))}
        </div>
      )}

      {word.correction !== undefined && word.correction !== '' && (
        <div className={styles.correction}>
          <div className={styles.correctionLabel}>{t('word.correctionBlock')}</div>
          {word.originalMeaning !== undefined && (
            <div className={styles.correctionOriginal}>
              <Bilingual lang={meaningLang}>{word.originalMeaning}</Bilingual>
            </div>
          )}
          <div className={styles.correctionText}>
            <Bilingual lang={meaningLang}>{word.correction}</Bilingual>
          </div>
        </div>
      )}
    </div>
  );
}
