/**
 * Turning a deck into a queue of cards.
 *
 * The engine decides which card type a word gets and which distractors go
 * with it; this module only feeds it local data and shapes the result for
 * the UI. Generation is seeded by user, notebook, day and deck, so a
 * session rebuilt after a reload shows the same cards in the same order.
 */
import {
  buildDeck,
  clozeOf,
  exampleSentences,
  firstMeaning,
  pickDistractors,
  seededRng,
  selectCardType,
  shuffleOptions,
  type CardType,
  type CardWord,
  type DailyLimits,
  type Deck,
  type DistractorCandidate,
  type Settings,
  type Word,
  type Kind,
} from '@lexpad/core';

/** One option on a multiple-choice or cloze card. */
export interface CardOption {
  wordId: string;
  label: string;
}

/** A card ready to be shown. */
export interface SessionCard {
  /** Unique within the session, so a re-queued card is its own entry. */
  key: string;
  word: Word;
  type: CardType;
  isNew: boolean;
  box: number;
  /** Present for multiple-choice and cloze. Includes the correct answer. */
  options?: CardOption[];
  /** The example with the headword blanked, for cloze. */
  clozeSentence?: string;
  /** The exact text the blank stands for. */
  clozeAnswer?: string;
  /** True when this is the second showing after a wrong answer. */
  requeued?: boolean;
}

/** What a deck needs to become cards. */
export interface BuildInput {
  words: readonly Word[];
  settings: Settings;
  deck: Deck;
  today: number;
  confusions: Map<string, number>;
  /** Limits the group deck, from "practise this group". */
  groupIds?: readonly string[] | undefined;
  /** What a level, topic or kind deck practises. */
  scope?: { level?: string; topic?: string; kind?: Kind } | undefined;
  /** Seeds the generator, so the same day and deck rebuild identically. */
  seed: string;
  /** The notebook's daily limits, for the daily deck (SRS v2). */
  limits?: DailyLimits | undefined;
}

/** How many options a choice card offers, the answer included. */
const OPTION_COUNT = 4;

/** Builds the session queue. */
export function buildCards(input: BuildInput): SessionCard[] {
  const rng = seededRng(input.seed);
  const plan = buildDeck(input.deck, input.words, input.settings, input.today, rng, {
    confusions: input.confusions,
    ...(input.groupIds ? { groupIds: input.groupIds } : {}),
    ...(input.scope?.level === undefined ? {} : { level: input.scope.level }),
    ...(input.scope?.topic === undefined ? {} : { topic: input.scope.topic }),
    ...(input.scope?.kind === undefined ? {} : { kind: input.scope.kind }),
    ...(input.limits === undefined ? {} : { limits: input.limits }),
  });

  const byId = new Map(input.words.map((word) => [word.id, word]));
  const pool: DistractorCandidate[] = input.words.map((word) => ({
    wordId: word.id,
    label: word.headword,
    category: word.category,
    ...(word.level === undefined ? {} : { level: word.level }),
  }));

  const cards: SessionCard[] = [];
  for (const [index, item] of plan.items.entries()) {
    const word = byId.get(item.wordId);
    if (!word) continue;
    const card = buildOne(word, {
      enabled: input.settings.cardTypes,
      isNew: item.isNew,
      index,
      force: plan.force,
      audio: plan.audio,
      pool,
      rng,
    });
    if (card) cards.push(card);
  }
  return cards;
}

interface BuildOneOptions {
  enabled: Settings['cardTypes'];
  isNew: boolean;
  index: number;
  force?: 'classic' | 'spell' | undefined;
  audio: boolean;
  pool: readonly DistractorCandidate[];
  rng: () => number;
}

/** Builds one card, or nothing when the word can carry none. */
export function buildOne(word: Word, options: BuildOneOptions): SessionCard | undefined {
  const cardWord: CardWord = {
    id: word.id,
    headword: word.headword,
    meaning: firstMeaning(word),
    examples: exampleSentences(word),
    ...(word.trickySpelling === undefined ? {} : { trickySpelling: word.trickySpelling }),
  };
  const box = word.progress?.box ?? 1;

  const type = selectCardType({
    word: cardWord,
    enabled: options.enabled,
    isNew: options.isNew,
    box,
    sessionIndex: options.index,
    roll: options.rng(),
    ...(options.force ? { force: options.force } : {}),
  });
  if (type === undefined) return undefined;

  const card: SessionCard = {
    key: `${word.id}:${options.index}`,
    word,
    // The audio deck shows classic cards with the front hidden.
    type: options.audio && type === 'classic' ? 'audio' : type,
    isNew: options.isNew,
    box,
  };

  if (type === 'mc' || type === 'cloze') {
    let answerLabel = word.headword;
    if (type === 'cloze') {
      const cloze = clozeOf(cardWord);
      if (!cloze) return undefined;
      card.clozeSentence = cloze.sentence;
      card.clozeAnswer = cloze.answer;
      answerLabel = cloze.answer;
    }
    const answer: DistractorCandidate = {
      wordId: word.id,
      label: answerLabel,
      category: word.category,
      ...(word.level === undefined ? {} : { level: word.level }),
    };
    const distractors = pickDistractors(answer, options.pool, OPTION_COUNT - 1, options.rng);
    // A choice with nothing to choose between is no test at all. A notebook
    // with one word, or a topic deck of one, falls back to a flashcard — the
    // prototype does the same for the very first practice.
    if (distractors.length === 0) {
      return { ...card, type: options.audio ? 'audio' : 'classic' };
    }
    card.options = shuffleOptions(answer, distractors, options.rng).map((option) => ({
      wordId: option.wordId,
      // Cloze options show only the head of a multi-form label.
      label: type === 'cloze' ? (option.label.split(/[/,]/)[0] ?? option.label).trim() : option.label,
    }));
  }

  return card;
}

/** Whether a card asks the learner to produce the word rather than recognise it. */
export function isProductive(type: CardType): boolean {
  return type === 'reverse' || type === 'spell';
}

/** Whether a card is answered by typing. */
export function isTyped(type: CardType): boolean {
  return type === 'spell';
}

/** Whether a card is answered by choosing an option. */
export function isChoice(type: CardType): boolean {
  return type === 'mc' || type === 'cloze';
}
