import type { Word } from '@lexpad/core';

/**
 * What is known about the word besides its meaning, as separate tags.
 *
 * It was one monospaced string, "adjective · B1 · personality". Three facts
 * joined by dots read as one fact nobody can parse, and a monospace face on
 * a label that is not data is costume.
 */
export function metaOf(word: Pick<Word, 'pos' | 'category'>): string[] {
  // The level stays on the word page (app audit 2026-10-22), and a topic
  // that only says the part of speech again ("adjective", "adjectives") or
  // says nothing ("general") is left out.
  const pos = (word.pos ?? '').trim();
  const topic = word.category.trim();
  const plain = (text: string): string => text.toLowerCase().replace(/[-_]/g, ' ');
  const repeats =
    topic === '' ||
    plain(topic) === 'general' ||
    (pos !== '' && (plain(topic) === plain(pos) || plain(topic) === `${plain(pos)}s`));
  return [pos, repeats ? '' : topic].filter((part) => part !== '');
}
