import { useEffect, useState } from 'react';
import { setMeta } from '@/db/schema.js';
import { setReminder } from '@/db/mutations.js';
import { t } from '@/i18n/index.js';
import { localTimeZone } from '@/lib/format.js';
import { reminderHour, shouldOfferReminder } from './reminderOffer.js';
import { startReminder } from '@/features/settings/reminders.js';
import { syncSoon } from '@/sync/store.js';
import styles from './FirstReminder.module.css';

/**
 * "Want a nudge tomorrow?" on the first session's summary (2026-10-09; it
 * used to be a switch in onboarding, before the learner had practised
 * anything). One line and one button, shown once: putting it on screen
 * counts as asking, and Not now or the button puts it away. Turning it on
 * is the moment the phone asks for permission, exactly as Settings does.
 */
export function FirstReminder(): React.JSX.Element | null {
  // Decided once, as the summary opens, and held: marking it asked must not
  // take it away while it is being read.
  const [offer, setOffer] = useState(false);
  useEffect(() => {
    let live = true;
    void shouldOfferReminder().then((wanted) => {
      if (!live || !wanted) return;
      setOffer(true);
      void setMeta('reminderAsked', true);
    });
    return () => {
      live = false;
    };
  }, []);
  const [time] = useState(() => reminderHour());
  const [result, setResult] = useState<'idle' | 'busy' | 'on' | 'denied' | 'closed'>('idle');

  if (!offer || result === 'closed') return null;
  if (result === 'on' || result === 'denied') {
    return (
      <p className={styles.done} role="status">
        {result === 'on' ? t('intro.remindDone', { time }) : t('settings.reminderDenied')}
      </p>
    );
  }
  return (
    <div className={styles.offer}>
      <p className={styles.text}>{t('intro.remindTitle')}</p>
      <div className={styles.actions}>
        <button
          type="button"
          className={styles.on}
          disabled={result === 'busy'}
          onClick={() => {
            setResult('busy');
            void (async () => {
              try {
                await setReminder(time, localTimeZone());
                void syncSoon();
                // Scheduling asks the phone for permission.
                const status = await startReminder();
                setResult(status === 'denied' ? 'denied' : 'on');
              } catch {
                setResult('idle');
              }
            })();
          }}
        >
          {t('intro.remindAt', { time })}
        </button>
        <button
          type="button"
          className={styles.later}
          onClick={() => {
            setResult('closed');
          }}
        >
          {t('intro.remindLater')}
        </button>
      </div>
    </div>
  );
}
