import { useEffect, useRef } from 'react';
import { firstMeaning, type LanguageCode } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { LANGUAGE_NAMES } from '@/features/settings/data.js';
import type { SessionCard } from '../build.js';
import { Speaker } from './Speaker.js';
import styles from './Card.module.css';

interface SpellCardProps {
  card: SessionCard;
  targetLang: LanguageCode;
  meaningLang: LanguageCode;
  outcome: 'correct' | 'wrong' | undefined;
  revealed: string | undefined;
  typed: string;
  onType: (value: string) => void;
  alt: boolean;
}

/**
 * The spelling drill. The meaning is shown with a dotted mask of the word's
 * shape, and the word is typed. A miss reveals the spelling along with any
 * note the entry carries.
 */
export function SpellCard({
  card,
  targetLang,
  meaningLang,
  outcome,
  revealed,
  typed,
  onType,
  alt,
}: SpellCardProps): React.JSX.Element {
  const input = useRef<HTMLInputElement>(null);

  useEffect(() => {
    input.current?.focus();
  }, [card.key]);

  // The right spelling after a miss: on a short phone it lands below the
  // fold once the keyboard goes, so it is brought into view.
  const reveal = useRef<HTMLDivElement>(null);
  const shown = revealed !== undefined;
  useEffect(() => {
    const box = reveal.current;
    // jsdom has no layout, and no scrollIntoView with it.
    if (shown && box !== null && 'scrollIntoView' in box) box.scrollIntoView({ block: 'nearest' });
  }, [shown]);

  const example = card.word.meanings?.[0]?.examples?.[0]?.sentence;

  return (
    <div className={cx(styles.stack, alt && styles.stackAlt)}>
      <div className={styles.spellPrompt}>
        <div className={styles.spellLabel}>
          {t('session.typePrompt', { language: LANGUAGE_NAMES[targetLang] })}
        </div>
        <div className={styles.choicePrompt}>
          <Bilingual lang={meaningLang}>{firstMeaning(card.word)}</Bilingual>
        </div>
        <div className={styles.mask}>{maskOf(card.word.headword)}</div>
      </div>

      <input
        ref={input}
        className={cx(
          styles.input,
          outcome === undefined && styles.inputFocus,
          outcome === 'correct' && styles.inputRight,
          outcome === 'wrong' && styles.inputWrong,
        )}
        value={typed}
        placeholder={t('session.typeHere')}
        aria-label={t('session.typeTheWord')}
        autoComplete="off"
        autoCorrect="off"
        autoCapitalize="off"
        spellCheck={false}
        disabled={outcome !== undefined}
        onChange={(event) => {
          onType(event.target.value);
        }}
      />

      {revealed !== undefined && (
        <div ref={reveal} className={styles.reveal}>
          <div className={styles.revealHead}>
            <span className={styles.revealWord}>
              <Bilingual lang={targetLang}>{revealed}</Bilingual>
            </span>
            <Speaker text={revealed} lang={targetLang} variant="reveal" />
          </div>
          {card.word.spellingNote !== undefined && card.word.spellingNote !== '' && (
            <div className={styles.revealNote}>
              <Bilingual lang={meaningLang}>{card.word.spellingNote}</Bilingual>
            </div>
          )}
          {example !== undefined && (
            <div className={styles.revealExample}>
              <Bilingual lang={targetLang}>{example}</Bilingual>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/** "a m b i t i o u s" as dots, with the letter count, per the prototype. */
function maskOf(headword: string): string {
  const dots = [...headword].map((char) => (/\p{L}/u.test(char) ? '·' : char)).join(' ');
  const letters = [...headword].filter((char) => /\p{L}/u.test(char)).length;
  return `${dots}  (${String(letters)})`;
}
