import { useEffect, useId, useRef, useState } from 'react';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import styles from './SessionMenu.module.css';

/**
 * The session's "⋯": the rarer things to do with this word — a note, its
 * details — behind one button (app audit 2026-10-22), so the card has one
 * row of chrome above it rather than two. A small menu: arrow keys move,
 * Escape and a tap outside close it, and focus goes back to the button.
 */
export function SessionMenu({
  onNote,
  onDetails,
}: {
  onNote: () => void;
  onDetails: () => void;
}): React.JSX.Element {
  const [open, setOpen] = useState(false);
  const button = useRef<HTMLButtonElement>(null);
  const list = useRef<HTMLDivElement>(null);
  const id = useId();

  useEffect(() => {
    if (!open) return undefined;
    list.current?.querySelector<HTMLButtonElement>('[role="menuitem"]')?.focus();
    const away = (event: PointerEvent): void => {
      const target = event.target as Node;
      if (list.current?.contains(target) === true || button.current?.contains(target) === true) return;
      setOpen(false);
    };
    document.addEventListener('pointerdown', away);
    return () => {
      document.removeEventListener('pointerdown', away);
    };
  }, [open]);

  const close = (): void => {
    setOpen(false);
    button.current?.focus();
  };
  const choose = (action: () => void): void => {
    setOpen(false);
    action();
  };
  const onKey = (event: React.KeyboardEvent): void => {
    // The session's own keys (space, arrows, S) stay with the menu while it is open.
    event.stopPropagation();
    const items = [...(list.current?.querySelectorAll<HTMLButtonElement>('[role="menuitem"]') ?? [])];
    const at = items.indexOf(document.activeElement as HTMLButtonElement);
    if (event.key === 'Escape') {
      event.preventDefault();
      close();
    } else if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault();
      const step = event.key === 'ArrowDown' ? 1 : -1;
      items[(at + step + items.length) % items.length]?.focus();
    } else if (event.key === 'Tab') {
      setOpen(false);
    }
  };

  return (
    <div className={styles.wrap}>
      <button
        ref={button}
        type="button"
        className={styles.button}
        aria-label={t('session.more')}
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={open ? id : undefined}
        onClick={() => {
          setOpen(!open);
        }}
      >
        <Icon name="more" size={20} weight={2} />
      </button>
      {open && (
        <div ref={list} id={id} role="menu" className={styles.menu} onKeyDown={onKey}>
          <button
            type="button"
            role="menuitem"
            className={styles.item}
            onClick={() => {
              choose(onNote);
            }}
          >
            <Icon name="note" size={17} weight={1.9} />
            {t('session.addNote')}
          </button>
          <button
            type="button"
            role="menuitem"
            className={styles.item}
            onClick={() => {
              choose(onDetails);
            }}
          >
            <Icon name="notebook" size={17} weight={1.9} />
            {t('session.details')}
          </button>
        </div>
      )}
    </div>
  );
}
