/**
 * The summary's moment: worked out from the session's own answers and a
 * few local reads, then claimed on the server so no other device of the
 * account shows it too. The summary draws once this is settled, so nothing
 * arrives late and pushes the page down.
 */
import { useEffect, useState } from 'react';
import { MASTERED_STEPS } from '@lexpad/core';
import { db, getMeta } from '@/db/schema.js';
import { lastPractisedBefore } from '@/features/learn/state.js';
import type { SessionSummary } from '@/features/session/useSession.js';
import type { TipId } from '@/features/learn/tips.js';
import { NOTHING, pickSummary, type MomentWord, type Pick, type SummarySignals } from './moments.js';
import {
  busyBefore,
  claimPick,
  countDueLeft,
  countMastered,
  isYoung,
  loadCelebrate,
  settleCelebrate,
} from './state.js';

/**
 * How long the local reads may take before the summary is drawn without a
 * moment. They are IndexedDB reads that land in a few frames; past this the
 * learner would see a blank screen, and no moment is better than that.
 */
export const SUMMARY_DECIDE_MS = 150;

const asWord = (word: { id: string; headword: string; notebookId: string }): MomentWord => ({
  id: word.id,
  headword: word.headword,
  notebookId: word.notebookId,
});

/** The moment for this summary, worked out once; null until settled. */
async function decide(
  summary: SessionSummary,
  tip: TipId | undefined,
): Promise<{ pick: Pick; today: number } | undefined> {
  const view = await loadCelebrate();
  if (!view.on) return undefined;
  const today = summary.today;
  const now = new Date();
  if (view.state === null) {
    await settleCelebrate(now, {
      reviewed: summary.reviewed,
      mastered: summary.mastered.length,
      streakBefore: summary.streakBefore,
      streakAfter: summary.streak,
    });
  }
  const state = await getMeta('celebrate');
  if (state === null) return undefined;
  const [dayStat, last, busy, masteredTotal, dueLeft, user] = await Promise.all([
    db.dayStats.get(today),
    lastPractisedBefore(today),
    busyBefore(today),
    countMastered(),
    countDueLeft(today),
    getMeta('user'),
  ]);
  const dayReviewed = dayStat?.reviewed ?? summary.reviewed;
  const flagged = new Set(state.flagged);
  const signals: SummarySignals = {
    reviewed: summary.reviewed,
    firstEver: last === undefined && dayReviewed <= summary.reviewed,
    moves: summary.moves.map((move) => ({ ...move, word: asWord(move.word) })),
    recalls: summary.recalls.map((recall) => ({ word: asWord(recall.word), days: recall.days })),
    slipBeaten: summary.recalls
      .filter((recall) => flagged.has(recall.word.id))
      .map((recall) => asWord(recall.word)),
    streak: summary.streak,
    streakBefore: summary.streakBefore,
    longestBefore: summary.longestBefore,
    masteredNow: summary.mastered.map(asWord),
    masteredTotal,
    dueLeft,
    dueAnswered: summary.dueAnswered,
    lastPractised: last,
    dayReviewed,
    bestBefore: busy.best,
    practiceDays: busy.days,
    masteredDays: MASTERED_STEPS[0],
  };
  const context = {
    today,
    young: isYoung(user?.createdAt, now),
    off: state.off,
    spent: new Set(state.spent),
    tip: tip !== undefined,
  };
  let pick = pickSummary(signals, context);
  // The first-mastered takeover says what its tip says: the tip is put away
  // (by the summary), so the screen is the moment's, line and all.
  if (tip === 'firstMastered' && pick.main?.id === 'firstMastered')
    pick = pickSummary(signals, { ...context, tip: false });
  return { pick, today };
}

/** Resolves with the value, or undefined once `ms` have passed. */
function race<T>(promise: Promise<T>, ms: number): Promise<T | undefined> {
  return Promise.race([
    promise,
    new Promise<undefined>((resolve) => {
      window.setTimeout(() => {
        resolve(undefined);
      }, ms);
    }),
  ]);
}

/**
 * Which moment the summary shows. `ready` is false until it is known: the
 * local reads (at most `SUMMARY_DECIDE_MS`) and, when there is something
 * to show, the server's answer (at most `CLAIM_WAIT_MS`). A session that is
 * not a moment waits only for the local reads.
 */
export function useSummaryMoment(
  summary: SessionSummary,
  /** The tip this summary would show, once known (undefined: none); the moment waits for it. */
  tip: { id: TipId | undefined } | null,
): { ready: boolean; pick: Pick } {
  const [result, setResult] = useState<{ ready: boolean; pick: Pick }>({ ready: false, pick: NOTHING });
  // The tip is read from local data in a few frames; a read that never
  // lands must not keep the summary blank, so past the bound it is "none".
  const [waitedOut, setWaitedOut] = useState(false);
  useEffect(() => {
    const timer = window.setTimeout(() => {
      setWaitedOut(true);
    }, SUMMARY_DECIDE_MS);
    return () => {
      window.clearTimeout(timer);
    };
  }, []);
  const known = tip !== null || waitedOut;
  const tipId = tip?.id;
  useEffect(() => {
    if (!known) return;
    const alive = { current: true };
    void (async () => {
      const decided = await race(
        decide(summary, tipId).catch(() => undefined),
        SUMMARY_DECIDE_MS,
      );
      if (decided === undefined) {
        if (alive.current) setResult({ ready: true, pick: NOTHING });
        return;
      }
      const claimed = await claimPick(decided.pick, decided.today).catch(() => NOTHING);
      if (alive.current) setResult({ ready: true, pick: claimed });
    })();
    return () => {
      alive.current = false;
    };
    // Decided once, for the session that just ended, once its tip is known.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [known]);
  return result;
}
